<script setup lang="ts">
import { computed, ref } from 'vue'
import { Check, Copy, Terminal, ArrowRight } from 'lucide-vue-next'
import ModalShell from './ModalShell.vue'
import { api, errorText } from '../api'
const props = defineProps<{ existing?: { id: string; name: string } }>()
const emit = defineEmits<{ close: []; created: [id: string] }>()
const name = ref(props.existing?.name || ''), group = ref(''), note = ref(''), busy = ref(false), error = ref(''), createdId = ref(props.existing?.id || '')
const install = ref<any>(null), platform = ref('linux'), proxy = ref(false), copied = ref(false), selectedInterface = ref('')
const localOnly = computed(() => { try { const host=new URL(install.value?.server || '').hostname; return host==='localhost'||host==='[::1]'||host==='0.0.0.0'||/^127\./.test(host) } catch { return false } })
const command = computed(() => { if (!install.value) return ''; if (platform.value === 'windows') return install.value.windows_command + (selectedInterface.value.trim() ? ` --interface '${selectedInterface.value.trim().replaceAll("'", "''")}'` : '') + (proxy.value ? ' --proxy' : ''); return proxy.value ? install.value.proxy_command : install.value.linux_command })
const run = computed(() => `.\\.venv\\Scripts\\python.exe -m sentinel.agent run --data "agent-data/${createdId.value}"`)
async function generate() { error.value = ''; busy.value = true; try { if (!createdId.value) { const result = await api('/nodes', 'POST', { name: name.value.trim(), group_name: group.value, note: note.value }); createdId.value = result.id; emit('created', result.id) }; install.value = await api(`/nodes/${createdId.value}/install`, 'POST'); if(localOnly.value) platform.value='windows' } catch (e) { error.value = errorText(e) } finally { busy.value = false } }
async function copy(value: string) { try { await navigator.clipboard.writeText(value); copied.value = true; setTimeout(() => copied.value = false, 1800) } catch { error.value = '浏览器不允许复制，请选中命令后手动复制。' } }
</script>
<template><ModalShell :title="install ? `安装 Agent · ${name}` : existing ? `重新注册 · ${name}` : '添加服务器'" wide @close="emit('close')"><form v-if="!install" class="stack" @submit.prevent="generate"><p class="muted">为服务器创建身份，然后在目标机器上运行专属安装命令。</p><label>服务器名称<input v-model="name" required maxlength="80" placeholder="例如：香港 01" :disabled="!!createdId" /></label><div v-if="!existing" class="form-grid"><label>分组（可选）<input v-model="group" maxlength="80" placeholder="例如：生产环境" :disabled="!!createdId" /></label><label>备注（可选）<input v-model="note" maxlength="500" placeholder="商家或用途" :disabled="!!createdId" /></label></div><div v-if="error" class="alert error" role="alert">{{ error }}</div><button class="primary" :disabled="busy || !name.trim()">{{ busy ? '正在生成…' : createdId ? '重新生成安装命令' : '创建并生成安装命令' }}<ArrowRight :size="16" /></button></form><div v-else class="stack"><div class="alert success"><Check :size="18" />注册凭据已生成，30 分钟内有效，仅能使用一次。</div><div class="form-grid"><label>目标系统<select v-model="platform"><option value="linux">Linux VPS</option><option value="windows">Windows 本地测试</option></select></label><label>连接方式<select v-model="proxy"><option :value="false">直连主控</option><option :value="true">SOCKS5 代理</option></select></label></div><div v-if="platform==='windows'" class="alert info">在本项目根目录打开 PowerShell。先运行注册命令，再运行下方采集命令；保持采集窗口开启。</div><label v-if="platform==='windows'">统计网卡（可选）<input v-model="selectedInterface" placeholder="例如：以太网，留空自动选择" /><small>可先运行 <code>.\.venv\Scripts\python.exe -m sentinel.agent interfaces</code> 查看名称，支持中文网卡名。</small></label><div v-if="platform==='linux' && localOnly" class="alert warn">当前主控地址仅能从本机访问，不能用于远程 VPS。请先在“系统设置”填写目标机器可达的主控地址，再重新生成安装命令。本地验证请选择“Windows 本地测试”。</div><div v-if="proxy && platform==='linux'" class="alert info">先在目标 VPS 创建 <code>proxy-curl.conf</code>，写入 <code>proxy = "socks5h://代理地址:端口"</code>，有认证时加入 <code>proxy-user = "用户名:密码"</code>。将文件权限设为 600。安装时会再次交互读取代理地址。</div><div v-if="platform==='windows' || !localOnly" class="code-block"><div class="code-title"><span><Terminal :size="15" />{{ platform === 'linux' ? '在目标 VPS 执行' : '1. 注册本地 Agent' }}</span><button class="text-button" @click="copy(command)"><component :is="copied ? Check : Copy" :size="15" />{{ copied ? '已复制' : '复制命令' }}</button></div><pre tabindex="0">{{ command }}</pre></div><div v-if="platform==='windows'" class="code-block"><div class="code-title"><span>2. 开始持续采集</span><button class="text-button" @click="copy(run)"><Copy :size="15" />复制命令</button></div><pre tabindex="0">{{ run }}</pre></div><p class="hint">节点上线后，在详情中配置计费规则并校准商家剩余额度。其他机器必须能访问主控地址 <strong>{{ install.server }}</strong>；如需修改，请先到“系统设置”更新公开地址。</p><div v-if="error" class="alert error" role="alert">{{ error }}</div><div class="actions"><button class="secondary" :disabled="busy" @click="generate">重新生成凭据</button><button class="primary" @click="emit('close')">返回服务器列表</button></div></div></ModalShell></template>
